export interface CompanyFeature {
  companyFeatureId?: number;
  companyId: number;
  featureKey: string;
  enabled: boolean;
  configJson: string | null;
  updatedByUserId?: number | null;
  created_At?: string;
  updated_at?: string;
}

export interface CompanyFeatureListResponse {
  companyFeatures: CompanyFeature[];
}

// GET ALL — POST /all_companyFeatures
export async function getAllCompanyFeatures(companyId: number, enabledOnly?: boolean): Promise<CompanyFeature[]> {
  const payload: Record<string, unknown> = { companyId };
  if (enabledOnly !== undefined) {
    payload.enabledOnly = enabledOnly ? 1 : 0;
  }
  const res = await fetch(BASE_URL + "/all_companyFeatures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "companyFeatures": [payload] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: CompanyFeatureListResponse = await res.json();
  return data.companyFeatures ?? [];
}

// CREATE — action: 1
export async function createCompanyFeature(payload: Omit<CompanyFeature, "companyFeatureId" | "created_At" | "updated_at">): Promise<CompanyFeature> {
  const res = await fetch(BASE_URL + "/companyFeatures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "companyFeatures": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updateCompanyFeature(id: number, payload: Partial<CompanyFeature>): Promise<CompanyFeature> {
  const res = await fetch(BASE_URL + "/companyFeatures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "companyFeatures": [{ "action": 2, "companyFeatureId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}
