  const [saving, setSaving] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [selectedItem, setSelectedItem] = useState<CompanyFeature | null>(null);
  const [formState, setFormState] = useState<CompanyFeatureFormState>({
    featureKey: '',
    enabled: false,
    configJson: null,
  });
  const [formErrors, setFormErrors] = useState<Partial<CompanyFeatureFormState>>({});

  const validateForm = useCallback(() => {
    const errors: Partial<CompanyFeatureFormState> = {};
    if (!formState.featureKey.trim()) {
      errors.featureKey = 'La clave de característica es requerida.';
    }
    if (formState.configJson && !isValidJson(formState.configJson)) {
      errors.configJson = 'El JSON de configuración no es válido.';
    }
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  }, [formState]);

  const isValidJson = (text: string) => {
    try {
      JSON.parse(text);
      return true;
    } catch (e) {
      return false;
    }
  };

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await getAllCompanyFeatures(companyId);
      setItems(data);
    } catch (err) {
      showToast((err as Error).message ?? 'Error cargando características', 'danger');
    } finally {
      setLoading(false);
    }
  }, [companyId, showToast]);

  useEffect(() => {
    load();
  }, [load]);

  useIonViewWillEnter(() => {
    load();
  });

  useEffect(() => onDataChanged(() => load()), [load]);

  const handleNew = () => {
    setIsEditing(false);
    setSelectedItem(null);
    setFormState({
      featureKey: '',
      enabled: false,
      configJson: null,
    });
    setFormErrors({});
    setShowModal(true);
  };

  const handleEdit = (item: CompanyFeature) => {
    setIsEditing(true);
    setSelectedItem(item);
    setFormState({
      featureKey: item.featureKey,
      enabled: item.enabled,
      configJson: item.configJson,
    });
    setFormErrors({});
    setShowModal(true);
  };

  const handleDismissModal = () => {
    setShowModal(false);
    setSelectedItem(null);
    setFormState({
      featureKey: '',
      enabled: false,
      configJson: null,
    });
    setFormErrors({});
  };

  const handleSave = async () => {
    if (!validateForm()) {
      showToast('Por favor, corrige los errores en el formulario.', 'danger');
      return;
    }

    setSaving(true);
    try {
      if (isEditing && selectedItem?.companyFeatureId) {
        await updateCompanyFeature(selectedItem.companyFeatureId, {
          featureKey: formState.featureKey,
          enabled: formState.enabled,
          configJson: formState.configJson,
          updatedByUserId: userId,
        });
        showToast('Característica actualizada con éxito.', 'success');
      } else {
        await createCompanyFeature({
          companyId,
          featureKey: formState.featureKey,
          enabled: formState.enabled,
          configJson: formState.configJson,
          updatedByUserId: userId,
        });
        showToast('Característica creada con éxito.', 'success');
      }
      notifyDataChanged('companyFeature-saved');
      handleDismissModal();
    } catch (err) {
      showToast((err as Error).message ?? 'Error al guardar la característica', 'danger');
    } finally {
      setSaving(false);
    }
  };

  return {
    items,
    loading,
    toastProps,
    showModal,
    isEditing,
    formState,
    setFormState,
    formErrors,
    saving,
    handleNew,
    handleEdit,
    handleDismissModal,
    handleSave,
  };
};

